// One item per configured feed URL; the single RSS node after this runs once
// per item. Empty slots are skipped, so one, three or ten feeds all work.
const cfg = $input.first().json;
const urls = (Array.isArray(cfg.feedUrls) ? cfg.feedUrls : [])
  .map((u) => String(u == null ? '' : u).trim())
  .filter((u) => /^https?:\/\//i.test(u));
if (!urls.length) {
  throw new Error('Config.feedUrls has no usable URLs. Add at least one RSS feed URL.');
}
return urls.map((feedUrl) => ({ json: { feedUrl } }));

// Merges every feed item into one deduped pool (last lookbackDays days, cap
// 40 headlines) and builds the curation prompt. A feed that failed simply
// contributes nothing - the run continues as long as ANY feed returned items.
const cfg = $('Config').first().json;
const items = $input.all().map((i) => i.json);
const now = new Date();
const lookbackMs = Math.max(1, Number(cfg.lookbackDays || 7)) * 86400000;

const domainOf = (link) => {
  const m = /^https?:\/\/([^\/:?#]+)/i.exec(String(link || ''));
  return m ? m[1].replace(/^www\./, '') : '';
};
const strip = (s) => String(s == null ? '' : s).replace(/<[^>]*>/g, ' ').replace(/&[a-zA-Z#0-9]+;/g, ' ').replace(/\s+/g, ' ').trim();

const seen = new Set();
const pool = [];
for (const it of items) {
  if (!it || !it.title || !it.link) continue; // error placeholders from a dead feed land here
  const title = strip(it.title);
  if (!title) continue;
  const when = new Date(it.isoDate || it.pubDate || NaN);
  if (!isNaN(when) && now - when > lookbackMs) continue; // undated items stay in
  const key = title.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 80);
  if (!key || seen.has(key)) continue;
  seen.add(key);
  pool.push({
    n: pool.length + 1,
    title: title.slice(0, 160),
    snippet: strip(it.contentSnippet || it.content || it.summary || '').slice(0, 200),
    source: domainOf(it.link),
    link: String(it.link),
  });
  if (pool.length >= 40) break;
}

if (!pool.length) {
  throw new Error('No usable stories in the last ' + (cfg.lookbackDays || 7) + ' days from any configured feed. Check Config.feedUrls, or raise lookbackDays.');
}

const lines = pool.map((p) => p.n + '. [' + (p.source || 'unknown') + '] ' + p.title + (p.snippet ? ' - ' + p.snippet : ''));
const promptText =
  'Niche: ' + cfg.niche + '\n' +
  'This week\'s pooled headlines (format: number. [source] title - snippet):\n' +
  lines.join('\n') + '\n\n' +
  'Pick the five most consequential stories for this niche and write a countdown script. Rules:\n' +
  '1. Return stories in COUNTDOWN order: the first array entry is number five, the last entry is number one, the single biggest story of the week.\n' +
  '2. headline: rewrite it punchy and neutral, twelve words or fewer, no clickbait, no trailing period.\n' +
  '3. blurb: exactly one spoken sentence of eighteen to twenty six words that a narrator reads aloud. Plain spoken words only: no digits (spell numbers out as words), no abbreviations, no quotes, no emoji, plain ASCII punctuation. Never say the rank number - the video shows it on screen.\n' +
  '4. index: the number of the pooled headline the story came from. The video prints that entry\'s real source, so never merge two pooled stories and never invent one.\n' +
  '5. visualQuery: two to four plain words naming concrete filmable stock footage for the story (an object, place or action - never an abstract idea).\n' +
  '6. intro: one spoken sentence, at most eighteen words, that opens the show, names the niche and teases the countdown.\n' +
  '7. outro: one spoken sentence, at most sixteen words, that signs off and invites the viewer to follow next week.\n' +
  '8. If the pool has fewer than five distinct stories, return as many as exist in the same shape.\n\n' +
  'Return exactly this JSON shape:\n' +
  '{\n' +
  '  "intro": "one sentence",\n' +
  '  "musicTag": "one of: ambient, cinematic, inspiring, chill, suspense, calm, dramatic, rock, piano",\n' +
  '  "stories": [{ "index": 12, "headline": "...", "blurb": "...", "visualQuery": "..." }],\n' +
  '  "outro": "one sentence"\n' +
  '}';

return [{ json: { ...cfg, promptText, pool, nowIso: now.toISOString(), pooled: pool.length } }];

// Parses the curator's JSON, normalises the copy to ASCII (curly quotes make
// the voice stumble and break caption word-matching), maps every story back
// to its pooled source, and builds the exact narration string sent to TTS.
const cfg = $('Config').first().json;
const poolNode = $('Pool headlines').first().json;
const res = $input.first().json;

const content = res && res.choices && res.choices[0] && res.choices[0].message ? res.choices[0].message.content : null;
if (!content) {
  throw new Error('The model returned no content: ' + JSON.stringify(res).slice(0, 400));
}

let rundown;
try {
  rundown = JSON.parse(content);
} catch (e) {
  const m = /\{[\s\S]*\}/.exec(content);
  if (!m) throw new Error('The model did not return JSON:\n' + content.slice(0, 400));
  rundown = JSON.parse(m[0]);
}

const toAscii = (s) =>
  String(s)
    .replace(/[\u2018\u2019\u02BC]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/\u2026/g, '...')
    .replace(/\s+/g, ' ')
    .trim();

let stories = Array.isArray(rundown.stories) ? rundown.stories.slice(0, 5) : [];
stories = stories.filter((s) => s && typeof s.headline === 'string' && typeof s.blurb === 'string' && s.headline.trim() && s.blurb.trim());
if (!stories.length) throw new Error('The model returned no usable stories.');

for (const s of stories) {
  s.headline = toAscii(s.headline).replace(/[.]+$/, '');
  const hw = s.headline.split(' ');
  if (hw.length > 16) s.headline = hw.slice(0, 16).join(' ');
  s.blurb = toAscii(s.blurb);
  s.visualQuery = toAscii(s.visualQuery || s.headline).split(' ').slice(0, 5).join(' ');
  // The on-screen source tag comes from the REAL pooled item, never from the
  // model - an invalid index just means the tag is omitted for that story.
  const src = (poolNode.pool || []).find((p) => p.n === Number(s.index));
  s.source = src ? src.source : '';
  s.link = src ? src.link : '';
}

const MUSIC_TAGS = ['ambient', 'cinematic', 'inspiring', 'chill', 'suspense', 'calm', 'dramatic', 'rock', 'piano'];
const musicTag = MUSIC_TAGS.includes(String(rundown.musicTag || '').toLowerCase())
  ? String(rundown.musicTag).toLowerCase()
  : 'cinematic';

const COUNT_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five'];
const intro = toAscii(rundown.intro || 'The ' + (COUNT_WORDS[stories.length] || stories.length) + ' stories that shaped ' + cfg.niche + ' this week, counted down.');
const outro = toAscii(rundown.outro || 'That is the week, follow along for the next countdown.');

const narration = [intro].concat(stories.map((s) => s.blurb)).concat([outro]).join(' ');
const wordCount = narration.split(/\s+/).filter(Boolean).length;
if (wordCount < 40) {
  throw new Error('The script is only ' + wordCount + ' words - too short for a roundup. Retry, or use a stronger model.');
}

return [{
  json: {
    intro,
    outro,
    stories,
    musicTag,
    narration,
    wordCount,
    niche: cfg.niche,
    nowIso: poolNode.nowIso,
    pooledCount: poolNode.pooled,
  },
}];

// One item per story so the stock search below runs once per story.
const rundown = $input.first().json;
return rundown.stories.map((s, index) => ({
  json: { index, headline: s.headline, visualQuery: s.visualQuery },
}));

// Picks one b-roll clip per story from Zvid's stock library. Portrait clips
// win because the canvas is 1080x1920 - a landscape clip still works via
// resize:"cover", it is just cropped harder. A story with no match gets a
// branded gradient panel in the builder, so missing footage NEVER fails a run.
const cfg = $('Config').first().json;
const rundown = $('Parse rundown').first().json;
const responses = $input.all();
const approxSceneSeconds = Number(cfg.targetSeconds || 60) / (rundown.stories.length + 2);

function pick(items, needSeconds) {
  const usable = (items || []).filter((it) => it && it.src);
  if (!usable.length) return null;
  return usable
    .map((it) => {
      const portrait = Number(it.height) > Number(it.width);
      const longEnough = Number(it.duration || 0) >= needSeconds;
      return {
        it,
        score: (portrait ? 2 : 0) + (longEnough ? 1 : 0) + Math.min(1, Number(it.duration || 0) / 30),
      };
    })
    .sort((a, b) => b.score - a.score)[0].it;
}

const sceneMedia = rundown.stories.map((_, i) => {
  const body = responses[i] && responses[i].json ? responses[i].json : {};
  const chosen = pick(body.items, approxSceneSeconds);
  if (!chosen) return null;
  return {
    kind: chosen.kind || 'video',
    src: chosen.src,
    duration: Number(chosen.duration) || null,
    width: Number(chosen.width) || null,
    height: Number(chosen.height) || null,
    credit: chosen.credit || null,
  };
});

const missing = sceneMedia.filter((m) => !m).length;
return [{ json: { sceneMedia, missing } }];

// The music catalogue is tag-matched and occasionally returns nothing for a
// tag that worked a minute ago, so ask for the curator's tag plus two broad
// fallbacks. One item per query -> the search node runs once per tag.
const tag = $('Parse rundown').first().json.musicTag;
const queries = [...new Set([tag, 'cinematic', 'ambient'])];
return queries.map((query) => ({ json: { query } }));

// Rank the music candidates. Long tracks mean big files, and the renderer
// rejects any asset over the plan's audio size cap - a 6 MB track fails the
// WHOLE render, so a nice-to-have music bed must never be able to do that.
// Shortest-but-long-enough wins; the next node probes the real byte size.
const cfg = $('Config').first().json;
const maxSeconds = Number(cfg.maxMusicSeconds == null ? 200 : cfg.maxMusicSeconds);

const seen = new Set();
const all = [];
for (const r of $input.all()) {
  for (const m of r.json.items || []) {
    if (!m || !m.src) continue;
    const key = m.id || m.src;
    if (seen.has(key)) continue;
    seen.add(key);
    all.push(m);
  }
}

const sized = all
  .filter((m) => { const d = Number(m.duration) || 0; return d >= 45 && d <= maxSeconds; })
  .sort((a, b) => (Number(a.duration) || 0) - (Number(b.duration) || 0));

const pool = (sized.length ? sized : all).slice(0, 4);
if (!pool.length) {
  // Nothing to probe, but the next node must still emit one item so the
  // pairing in "Pick music" stays aligned. Point it at the API health check:
  // a 2-byte 200 that exists for exactly this kind of ping.
  return [{ json: { candidate: null, probeUrl: String(cfg.apiUrl).replace(/\/+$/, '') + '/healthz' } }];
}
return pool.map((candidate) => ({ json: { candidate, probeUrl: candidate.src } }));

// Keep the first candidate that is actually downloadable and within the size
// cap, then collapse to ONE item - otherwise the voiceover step downstream
// would run once per candidate. No usable track just means no music bed; it
// must never fail the run.
const cfg = $('Config').first().json;
const limit = Number(cfg.maxMusicBytes == null ? 5242880 : cfg.maxMusicBytes);
const shortlist = $('Shortlist music').all().map((i) => i.json);
const probes = $input.all();

let music = null;
const rejected = [];
for (let i = 0; i < probes.length; i += 1) {
  const candidate = shortlist[i] && shortlist[i].candidate;
  if (!candidate) continue;
  const p = probes[i] ? probes[i].json : {};
  const status = Number(p.statusCode);
  const headers = p.headers || {};
  const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);

  if (status !== 200) { rejected.push(candidate.id + ': HTTP ' + (status || '?')); continue; }
  if (bytes && bytes > limit) { rejected.push(candidate.id + ': ' + bytes + ' bytes > ' + limit); continue; }
  music = candidate;
  break;
}

return [{ json: { music, checked: probes.length, rejected } }];

// Turns one ElevenLabs "with-timestamps" response into (a) an mp3 binary ready
// for upload and (b) word timings.
//
// The alignment comes from the synthesiser itself, so the timings ARE the audio
// - there is no separate transcription step to disagree with, and nothing that
// can drift. That is the whole reason this endpoint is used instead of plain
// text-to-speech.
const res = $input.first().json;

if (!res || !res.audio_base64) {
  throw new Error(
    'ElevenLabs returned no audio. Check the xi-api-key credential, the voiceId, and your character quota. Response: ' +
      JSON.stringify(res).slice(0, 300)
  );
}

const a = res.alignment || res.normalized_alignment;
if (!a || !Array.isArray(a.characters)) {
  throw new Error('ElevenLabs returned audio but no alignment - make sure the URL ends in /with-timestamps.');
}

const chars = a.characters;
const starts = a.character_start_times_seconds || [];
const ends = a.character_end_times_seconds || [];

// Alignment is per CHARACTER; group runs of non-whitespace into words.
const words = [];
let cur = null;
for (let i = 0; i < chars.length; i += 1) {
  const ch = chars[i];
  if (/\s/.test(ch)) {
    if (cur) { words.push(cur); cur = null; }
    continue;
  }
  if (!cur) cur = { text: ch, start: Number(starts[i]), end: Number(ends[i]) };
  else { cur.text += ch; cur.end = Number(ends[i]); }
}
if (cur) words.push(cur);

if (!words.length) throw new Error('Alignment contained no words.');

const duration = Number(ends[ends.length - 1]) || words[words.length - 1].end;

return [{
  json: { words, duration, wordCount: words.length },
  // n8n binary payloads carry base64 in 'data'; naming it matters because Zvid
  // derives the media kind from the MIME type on upload.
  binary: {
    data: {
      data: res.audio_base64,
      mimeType: 'audio/mpeg',
      fileName: 'voiceover.mp3',
      fileExtension: 'mp3',
    },
  },
}];

// === buildRoundup — identical to the frame-reviewed standalone builder ===
// Assembles the Zvid project: branded cold open, five countdown story scenes
// (5 → 1) with b-roll + headline cards + source tags, outro CTA, word-timed
// karaoke captions riding the narration, and an optional music bed.
function buildRoundup(cfg, data) {
  const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
  const round = (n) => Math.round(n * 100) / 100;
  const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  // SVG + inline CSS need rgba() variants of the two brand hexes.
  const rgba = (hex, a) => {
    const h = String(hex || '').replace('#', '');
    const f = h.length === 3 ? h.split('').map((c) => c + c).join('') : (h + '000000').slice(0, 6);
    const n = parseInt(f, 16);
    return 'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + a + ')';
  };

  const rundown = data.rundown || {};
  const stories = Array.isArray(rundown.stories) ? rundown.stories : [];
  if (!stories.length) throw new Error('The rundown has no stories to render.');
  const storyCount = Math.min(stories.length, 5);

  const bg = clean(cfg.brandBackground) || '#0D1117';
  const accent = clean(cfg.brandAccent) || '#FFC24B';
  const paper = clean(cfg.headlineColor) || '#FFFFFF';
  const muted = clean(cfg.mutedColor) || '#9AA3B2';
  const font = clean(cfg.font) || 'Archivo';
  const brandName = clean(cfg.brandName) || 'The Weekly Signal';
  const brandUpper = esc(brandName.toUpperCase());
  const niche = clean(rundown.niche || cfg.niche) || 'the news';
  const nicheUpper = esc(niche.toUpperCase());
  const ctaText = clean(cfg.ctaText) || 'Follow for next week';

  // ---- dateline -----------------------------------------------------------
  // Derived from the pooling step's clock so a re-run of the same execution
  // reproduces the same video (no Date.now() in the design path).
  const now = rundown.nowIso ? new Date(rundown.nowIso) : new Date();
  const lookback = Math.max(1, Number(cfg.lookbackDays || 7));
  const startD = new Date(now.getTime() - (lookback - 1) * 86400000);
  const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
  const fmtDay = (d) => MONTHS[d.getUTCMonth()] + ' ' + d.getUTCDate();
  const dateline = 'WEEK OF ' + fmtDay(startD) + ' – ' + fmtDay(now);
  const COUNT_WORDS = ['', 'ONE', 'TWO', 'THREE', 'FOUR', 'FIVE'];

  // ---- adaptive type ------------------------------------------------------
  // Greedy word-wrap estimate. avgEm is calibrated per weight/case AND biased
  // high on purpose: over-counting lines only pushes a block further down
  // empty canvas, while under-counting collides it with the block below.
  // (Measured against the production renderer: heavy uppercase Archivo runs
  // ~0.74 em per character, and letter-spacing has to be paid for on top.)
  const wrapLines = (text, fontPx, boxPx, avgEm) => {
    const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
    let lines = 1;
    let used = 0;
    for (const w of String(text).split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      lines += 1;
      used = Math.min(w.length, perLine);
    }
    return lines;
  };

  // ---- narration timing ---------------------------------------------------
  const timings = data.timings || {};
  const words = (Array.isArray(timings.words) ? timings.words : [])
    .map((w) => ({ text: String(w.text == null ? '' : w.text).trim(), start: Number(w.start), end: Number(w.end) }))
    .filter((w) => w.text && Number.isFinite(w.start) && Number.isFinite(w.end));
  const narrationEnd = words.length ? words[words.length - 1].end : Number(timings.duration) || 45;
  const audioDuration = Math.max(Number(timings.duration) || 0, narrationEnd);

  const countWords = (s) =>
    String(s || '').replace(/[^\p{L}\p{N}'’]+/gu, ' ').trim().split(/\s+/).filter(Boolean).length;

  // Source chips are display chrome, not data. A 60-character hyphenated host
  // wraps to two lines and visually out-ranks the headline it is labelling, so
  // the chip shows the registrable domain, ellipsised on a hyphen boundary.
  // meta.countdown still reports every story's untouched source.
  const shortenSource = (raw) => {
    const parts = String(raw).split('.').filter(Boolean);
    let d = String(raw);
    if (parts.length > 2) {
      const tail = parts.slice(-2);
      // 'news.bbc.co.uk' keeps three labels; 'www.theverge.com' keeps two.
      d = (tail[0].length <= 3 && tail[1].length <= 3 ? parts.slice(-3) : tail).join('.');
    }
    if (d.length <= 28) return d;
    const cut = d.slice(0, 27);
    const brk = cut.lastIndexOf('-');
    return (brk >= 14 ? cut.slice(0, brk) : cut) + '…';
  };

  // Segments: intro, one blurb per story (countdown order), outro.
  const segTexts = [clean(rundown.intro)].concat(stories.slice(0, storyCount).map((s) => clean(s.blurb))).concat([clean(rundown.outro)]);
  const perSeg = segTexts.map(countWords);
  const totalScripted = perSeg.reduce((a, b) => a + b, 0);

  // Walking the alignment by per-segment word count puts every cut on a
  // sentence boundary; a proportional split is the safety net (digits or
  // abbreviations the model failed to spell out).
  const drift = totalScripted ? Math.abs(words.length - totalScripted) / totalScripted : 1;
  const useWordMap = words.length > 0 && drift <= 0.2;

  const spans = [];
  if (useWordMap) {
    let cursor = 0;
    for (let i = 0; i < perSeg.length; i += 1) {
      const start = cursor === 0 ? 0 : words[cursor - 1].end;
      cursor = Math.min(cursor + perSeg[i], words.length);
      const last = words[cursor - 1];
      spans.push({ start, end: i === perSeg.length - 1 ? audioDuration : last ? last.end : audioDuration });
    }
  } else {
    const weightTotal = totalScripted || perSeg.length;
    let t = 0;
    for (let i = 0; i < perSeg.length; i += 1) {
      const start = t;
      t = i === perSeg.length - 1 ? audioDuration : t + ((perSeg[i] || 1) / weightTotal) * audioDuration;
      spans.push({ start, end: t });
    }
  }
  spans[spans.length - 1].end += Number(cfg.tailSeconds == null ? 0.4 : cfg.tailSeconds);

  const transition = cfg.sceneTransition || null;
  const tDur = transition ? Number(cfg.transitionSeconds == null ? 0.4 : cfg.transitionSeconds) : 0;
  const minScene = Math.max(1.2, tDur * 3);

  // ---- shared SVG pieces --------------------------------------------------
  // Card panel for the intro and outro. The diagonal brand mark lives in the
  // BOTTOM-right quadrant: the header band belongs to the brand chip, whose
  // width follows a user-supplied brandName and therefore cannot be reasoned
  // about. Below y=1400 both cards are empty (intro copy ends by ~1240, outro
  // copy by ~1370) and the mark clears the 1770 rule, so no length of any
  // Config string can reach it.
  const brandPanelSvg = (idTag) =>
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><radialGradient id='" + idTag + "' cx='0.3' cy='0.22' r='1.15'>" +
    "<stop offset='0' stop-color='" + accent + "' stop-opacity='0.14'/>" +
    "<stop offset='1' stop-color='" + accent + "' stop-opacity='0'/></radialGradient></defs>" +
    "<rect width='1080' height='1920' fill='" + bg + "'/>" +
    "<rect width='1080' height='1920' fill='url(#" + idTag + ")'/>" +
    "<rect x='48' y='48' width='984' height='1824' fill='none' stroke='" + rgba(accent, 0.26) + "' stroke-width='1.5'/>" +
    "<path d='M872 1440 L936 1440 L836 1644 L772 1644 Z' fill='" + rgba(accent, 0.5) + "'/>" +
    "<path d='M956 1440 L992 1440 L892 1644 L856 1644 Z' fill='" + rgba(accent, 0.28) + "'/>" +
    "<path d='M90 1770 H990' stroke='" + rgba(accent, 0.24) + "' stroke-width='1.5'/>" +
    '</svg>';

  // Panel for a story scene whose stock search found nothing — a designed
  // alternative, not a blank canvas. It carries the same hairline frame as the
  // intro/outro cards (family resemblance), a halftone dot field that ramps
  // along the diagonal, and the slash motif tucked under the countdown numeral,
  // so the scene reads as part of the title sequence rather than as missing
  // media. It deliberately ships NO corner mark and NO second numeral: the
  // header row and the numeral column already belong to the scene chrome, and a
  // giant ghost digit read as a rendering fault instead of a treatment.
  // The dot field runs y 396-1146 — the same region a clip would have filled,
  // captions included (they ride b-roll on every other scene, and a 64 px
  // caption with a 6 px black stroke sits over a 24 %-accent dot exactly as
  // happily as it sits over footage). It stops above the headline card's
  // highest possible top edge (y 1140). The slash motif and the numeral share
  // the left column; the section label owns y 252-370 on the right.
  const storyFallbackSvg = (idTag) => {
    let dots = '';
    for (let c = 0; c < 13; c += 1) {
      for (let r = 0; r < 16; r += 1) {
        const dx = 412 + c * 46;
        const dy = 396 + r * 50;
        const t = clamp(((dx - 412) / 552 + (1146 - dy) / 750) / 2, 0, 1);
        dots +=
          "<circle cx='" + dx + "' cy='" + dy + "' r='" + round(2.4 + 6.6 * t) +
          "' fill='" + rgba(accent, round(0.07 + 0.27 * t)) + "'/>";
      }
    }
    return (
      "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>" +
      "<defs><radialGradient id='" + idTag + "' cx='0.32' cy='0.28' r='1.15'>" +
      "<stop offset='0' stop-color='" + accent + "' stop-opacity='0.18'/>" +
      "<stop offset='1' stop-color='" + accent + "' stop-opacity='0'/></radialGradient></defs>" +
      "<rect width='1080' height='1920' fill='" + bg + "'/>" +
      "<rect width='1080' height='1920' fill='url(#" + idTag + ")'/>" +
      "<rect x='48' y='48' width='984' height='1824' fill='none' stroke='" + rgba(accent, 0.2) + "' stroke-width='1.5'/>" +
      dots +
      "<path d='M232 520 L296 520 L176 872 L112 872 Z' fill='" + rgba(accent, 0.2) + "'/>" +
      "<path d='M320 520 L352 520 L232 872 L200 872 Z' fill='" + rgba(accent, 0.1) + "'/>" +
      '</svg>'
    );
  };

  const scrimSvg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><linearGradient id='wnrScrim' x1='0' y1='0' x2='0' y2='1'>" +
    "<stop offset='0' stop-color='" + bg + "' stop-opacity='0.62'/>" +
    "<stop offset='0.34' stop-color='" + bg + "' stop-opacity='0.12'/>" +
    "<stop offset='0.62' stop-color='" + bg + "' stop-opacity='0.3'/>" +
    "<stop offset='1' stop-color='" + bg + "' stop-opacity='0.94'/></linearGradient></defs>" +
    "<rect width='1080' height='1920' fill='url(#wnrScrim)'/>" +
    '</svg>';

  // ---- scenes -------------------------------------------------------------
  const kenBurns = Number(cfg.kenBurnsDepth == null ? 1.12 : cfg.kenBurnsDepth);
  const sceneMedia = Array.isArray(data.sceneMedia) ? data.sceneMedia : [];
  const scenes = [];
  let missingClips = 0;

  spans.forEach((span, i) => {
    const visible = Math.max(minScene, round(span.end - span.start));
    const isLast = i === spans.length - 1;
    const dur = round(visible + (isLast ? 0 : tDur));
    const isIntro = i === 0;
    const isOutro = i === spans.length - 1;

    if (isIntro) {
      const nLen = niche.length;
      const nSize = nLen <= 12 ? 108 : nLen <= 20 ? 92 : nLen <= 32 ? 72 : nLen <= 52 ? 58 : nLen <= 80 ? 48 : 40;
      const nLines = wrapLines(niche.toUpperCase(), nSize, 900, 0.74);
      const metaY = Math.min(1120, 480 + 66 + Math.round(nLines * nSize * 1.06) + 44);
      // The intro chip carries brandName, which is free-form Config copy. Box it
      // to the 900px safe column and ramp the type down so it stays one line and
      // inside the frame at any realistic length instead of growing without limit.
      // Budget: iLen * (iSize * 0.66 + iTrack) + 60px padding must stay under the
      // 900px column, so every step below is checked against that at its own
      // upper bound (54 chars at 16px = 846px, 90 chars at 14px wraps but still
      // cannot leave the box).
      const iLen = brandName.length;
      const iSize = iLen <= 20 ? 26 : iLen <= 30 ? 23 : iLen <= 42 ? 19 : iLen <= 54 ? 16 : 14;
      const iTrack = iLen <= 30 ? 6 : iLen <= 42 ? 5 : 4;
      scenes.push({
        id: 'intro',
        duration: dur,
        backgroundColor: bg,
        ...(transition && !isLast ? { transition, transitionDuration: tDur } : {}),
        visuals: [
          { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: dur, svg: brandPanelSvg('wnrIntro') },
          {
            type: 'TEXT', x: 540, y: 170, width: 900, anchor: 'top-center', track: 1, enterBegin: 0.1, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: dur,
            style: { fontFamily: font, color: accent },
            html: "<div style=\"text-align:center;\"><span style=\"display:inline-block; background:" + accent + '; color:' + bg + '; padding:12px 30px; font-size:' + iSize + "px; font-weight:900; letter-spacing:" + iTrack + "px; border-radius:6px;\">" + brandUpper + '</span></div>',
          },
          {
            type: 'TEXT', x: 540, y: 480, width: 900, anchor: 'top-center', track: 2, enterBegin: 0.35, enterEnd: 0.9, enterAnimation: 'smoothup', exitEnd: dur,
            style: { fontFamily: font, color: paper },
            html: "<div style=\"text-align:center; color:" + muted + "; font-size:30px; font-weight:800; letter-spacing:12px;\">THE WEEK IN</div>" +
              "<div style=\"margin-top:22px; text-align:center; color:" + paper + '; font-size:' + nSize + "px; line-height:1.06; font-weight:900; letter-spacing:-1px;\">" + nicheUpper + '</div>',
          },
          {
            type: 'TEXT', x: 540, y: metaY, width: 900, anchor: 'top-center', track: 3, enterBegin: 0.7, enterEnd: 1.15, enterAnimation: 'fade', exitEnd: dur,
            style: { fontFamily: font, color: accent },
            html: "<div style=\"text-align:center;\"><span style=\"display:inline-block; border:1.5px solid " + rgba(accent, 0.55) + '; color:' + accent + "; padding:10px 24px; font-size:26px; font-weight:800; letter-spacing:4px; border-radius:6px;\">" + esc(dateline) + '</span></div>' +
              "<div style=\"margin-top:26px; text-align:center; color:" + muted + "; font-size:26px; font-weight:700; letter-spacing:5px;\">THE " + (COUNT_WORDS[storyCount] || storyCount) + ' STORIES THAT MATTERED</div>',
          },
        ],
      });
      return;
    }

    if (isOutro) {
      const bLen = brandName.length;
      const bSize = bLen <= 14 ? 92 : bLen <= 22 ? 76 : bLen <= 34 ? 60 : 50;
      // A brand name long enough to wrap gets a narrower measure than the 900px
      // element, which breaks it into two balanced lines instead of one full
      // line plus a one-word orphan sitting edge to edge in the box.
      const bWidth = bLen <= 22 ? 900 : 780;
      const cLen = ctaText.length;
      const cSize = cLen <= 24 ? 34 : cLen <= 40 ? 28 : 24;
      scenes.push({
        id: 'outro',
        duration: dur,
        backgroundColor: bg,
        visuals: [
          { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: dur, svg: brandPanelSvg('wnrOutro') },
          {
            type: 'TEXT', x: 540, y: 520, width: 900, anchor: 'top-center', track: 1, enterBegin: 0.2, enterEnd: 0.7, enterAnimation: 'smoothup', exitEnd: dur,
            style: { fontFamily: font, color: paper },
            html: "<div style=\"text-align:center; color:" + muted + "; font-size:28px; font-weight:800; letter-spacing:8px;\">THAT IS YOUR WEEK</div>" +
              "<div style=\"margin:24px auto 0; max-width:" + bWidth + 'px; text-align:center; color:' + paper + '; font-size:' + bSize + "px; line-height:1.08; font-weight:900; letter-spacing:-1px;\">" + brandUpper + '</div>',
          },
          {
            type: 'TEXT', x: 540, y: 1230, anchor: 'top-center', track: 2, enterBegin: 0.6, enterEnd: 1.05, enterAnimation: 'circleopen', exitEnd: dur,
            style: { fontFamily: font, color: accent },
            html: "<div style=\"display:inline-block; background:" + accent + '; color:' + bg + '; border-radius:999px; padding:22px 54px; font-size:' + cSize + "px; font-weight:800;\">" + esc(ctaText) + '</div>' +
              "<div style=\"margin-top:22px; text-align:center; color:" + muted + "; font-size:24px; font-weight:700; letter-spacing:4px;\">NEW ROUNDUP EVERY WEEK</div>",
          },
        ],
      });
      return;
    }

    // ---- countdown story scene ---------------------------------------------
    const story = stories[i - 1];
    const rank = storyCount - (i - 1);
    const media = sceneMedia[i - 1] || null;
    const visuals = [];

    // Header collision guard: a long brand name shrinks the chip, and if chip
    // + dateline still cannot share the 900px header row, the dateline is
    // dropped on story scenes (the intro card already carries it).
    const chipFs = brandName.length <= 20 ? 22 : brandName.length <= 40 ? 18 : 15;
    const chipW = brandName.length * chipFs * 0.66 + 40;
    const dateW = dateline.length * 22 * 0.68;
    const showDateTag = chipW + dateW <= 860;

    let trackNo = 0;
    let hasBroll = false;
    if (media && media.kind === 'video' && media.src) {
      hasBroll = true;
      // videoEnd is measured in SOURCE time: a clip played at speed s covers
      // visible*s seconds of source. Slowing a short clip beats freezing it.
      const speed = media.duration && media.duration < visible
        ? clamp(round(media.duration / visible), 0.5, 1)
        : 1;
      const sourceWindow = round(visible * speed);
      visuals.push({
        type: 'VIDEO',
        src: media.src,
        resize: 'cover',
        position: 'center-center',
        anchor: 'center-center',
        volume: 0,
        videoBegin: 0,
        videoEnd: media.duration ? Math.min(media.duration, sourceWindow) : sourceWindow,
        ...(speed !== 1 ? { speed } : {}),
        zoom: { depth: kenBurns },
        track: trackNo++,
      });
    } else if (media && media.kind === 'image' && media.src) {
      hasBroll = true;
      visuals.push({
        type: 'IMAGE', src: media.src, resize: 'cover', position: 'center-center', anchor: 'center-center',
        exitEnd: dur, zoom: { depth: Math.max(kenBurns, 1.18) }, track: trackNo++,
      });
    } else {
      missingClips += 1;
      visuals.push({ type: 'SVG', width: 1080, height: 1920, track: trackNo++, enterBegin: 0, exitEnd: dur, svg: storyFallbackSvg('wnrFall' + rank) });
    }

    // The scrim exists to sit b-roll down under the captions and cards. The
    // fallback panel is already a dark designed surface, so scrimming it would
    // only wash out its own halftone field.
    if (hasBroll) {
      visuals.push({ type: 'SVG', width: 1080, height: 1920, track: trackNo++, enterBegin: 0, exitEnd: dur, svg: scrimSvg });
    }

    // Brand tag + dateline header.
    visuals.push({
      type: 'TEXT', x: 90, y: 96, width: 900, anchor: 'top-left', track: trackNo++, enterBegin: 0.1, enterEnd: 0.45, enterAnimation: 'fade', exitEnd: dur,
      style: { fontFamily: font, color: accent },
      html: "<div style=\"display:inline-block; background:" + accent + '; color:' + bg + '; padding:10px 20px; font-size:' + chipFs + "px; font-weight:900; letter-spacing:4px; border-radius:5px;\">" + brandUpper + '</div>',
    });
    if (showDateTag) {
      visuals.push({
        type: 'TEXT', x: 990, y: 104, anchor: 'top-right', track: trackNo++, enterBegin: 0.15, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: dur,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: "<div style=\"color:rgba(255,255,255,0.78); font-size:22px; font-weight:700; letter-spacing:3px; text-shadow:0 2px 10px rgba(0,0,0,0.6);\">" + esc(dateline) + '</div>',
      });
    }

    // Giant countdown number.
    visuals.push({
      type: 'TEXT', x: 84, y: 214, anchor: 'top-left', track: trackNo++, enterBegin: 0.1, enterEnd: 0.55, enterAnimation: 'smoothright', exitEnd: dur,
      style: { fontFamily: font, color: accent },
      html: "<div style=\"color:" + accent + "; font-size:250px; line-height:0.9; font-weight:900; letter-spacing:-6px; text-shadow:0 10px 60px rgba(0,0,0,0.55);\">" + rank + '</div>' +
        "<div style=\"width:120px; height:8px; background:" + accent + "; margin-top:12px; border-radius:4px;\"></div>",
    });

    // Fallback scenes only: a right-aligned section label fills the void a clip
    // would have occupied. Boxed to 620px (x 370-990) so it can never reach the
    // numeral column, and ramped down by niche length so it stays within
    // y 252-370 — clear of the dateline above and the dot field below.
    if (!hasBroll) {
      const fLen = niche.length;
      const fSize = fLen <= 20 ? 34 : fLen <= 34 ? 30 : 26;
      visuals.push({
        type: 'TEXT', x: 680, y: 252, width: 620, anchor: 'top-center', track: trackNo++, enterBegin: 0.25, enterEnd: 0.8, enterAnimation: 'fade', exitEnd: dur,
        style: { fontFamily: font, color: accent },
        html: "<div style=\"width:88px; height:3px; background:" + accent + "; margin-left:auto;\"></div>" +
          "<div style=\"margin-top:14px; text-align:right; color:" + muted + "; font-size:20px; font-weight:800; letter-spacing:6px;\">THE WEEK IN</div>" +
          "<div style=\"margin-top:8px; text-align:right; color:" + accent + '; font-size:' + fSize + "px; line-height:1.1; font-weight:900; letter-spacing:1px;\">" + nicheUpper + '</div>',
      });
    }

    // Headline card with source tag; grows upward from a fixed baseline.
    const headline = clean(story.headline);
    const source = shortenSource(clean(story.source)).toUpperCase();
    const hLen = headline.length;
    const hSize = hLen <= 34 ? 62 : hLen <= 52 ? 56 : hLen <= 72 ? 50 : 44;
    const hLines = wrapLines(headline, hSize, 828, 0.58);
    const srcSize = source.length > 24 ? 20 : 22;
    // The source tag is a bordered chip INSIDE the card, so it loses the card
    // padding (72) plus its own (28); at 3 px letter-spacing every character
    // costs roughly 0.78 em + 3 px, which is what 0.95 em stands in for. A
    // long hyphenated domain wraps to two lines and the card must grow for it.
    const srcLines = source ? wrapLines(source, srcSize, 800, 0.95) : 0;
    const srcRow = source ? srcLines * (srcSize + 12) + 18 : 0;
    const cardH = 30 + srcRow + Math.round(hLines * hSize * 1.12) + 34;
    const cardY = clamp(1760 - cardH, 1140, 1560);
    visuals.push({
      type: 'TEXT', x: 90, y: cardY, width: 900, anchor: 'top-left', track: trackNo++, enterBegin: 0.3, enterEnd: 0.8, enterAnimation: 'smoothup', exitEnd: dur,
      style: { fontFamily: font, color: paper },
      html: "<div style=\"background:" + rgba(bg, 0.86) + '; border-left:8px solid ' + accent + "; border-radius:8px; padding:30px 36px 34px 36px;\">" +
        (source
          ? "<div style=\"display:inline-block; color:" + accent + '; border:1.5px solid ' + rgba(accent, 0.5) + '; border-radius:5px; padding:6px 14px; font-size:' + srcSize + "px; font-weight:800; letter-spacing:3px;\">" + esc(source) + '</div>'
          : '') +
        "<div style=\"" + (source ? 'margin-top:18px; ' : '') + 'color:' + paper + '; font-size:' + hSize + "px; line-height:1.12; font-weight:900; letter-spacing:-1px;\">" + esc(headline) + '</div>' +
        '</div>',
    });

    scenes.push({
      id: 'story-' + rank,
      duration: dur,
      backgroundColor: bg,
      ...(transition && !isLast ? { transition, transitionDuration: tDur } : {}),
      visuals,
    });
  });

  const totalDuration = round(
    scenes.reduce((sum, s) => sum + s.duration, 0) - tDur * Math.max(0, scenes.length - 1)
  );

  // ---- captions -----------------------------------------------------------
  const perCueCfg = Math.max(1, Number(cfg.captionWordsPerCue == null ? 3 : cfg.captionWordsPerCue));
  // The plan caps a project at 200 caption cues, and the whole project is
  // rejected if it goes over. A long script at captionWordsPerCue: 1 can reach
  // that, so group more words per cue rather than fail the run.
  const MAX_CUES = 200;
  const perCue = Math.max(perCueCfg, Math.ceil(words.length / MAX_CUES) || 1);
  const captions = [];
  for (let i = 0; i < words.length; i += perCue) {
    const chunk = words.slice(i, i + perCue);
    captions.push({
      start: chunk[0].start,
      end: chunk[chunk.length - 1].end,
      text: chunk.map((w) => w.text).join(' '),
      words: chunk.map((w) => ({ start: w.start, end: w.end, text: w.text })),
    });
  }

  const BOX_MODES = ['highlight'];
  const animation = cfg.captionAnimation || 'karaoke';
  const usesBox = BOX_MODES.includes(animation);
  const strokeWidth = Math.max(0, Number(cfg.captionStrokeWidth == null ? 6 : cfg.captionStrokeWidth));

  const subtitle = {
    captions,
    animation,
    activeWord: usesBox
      ? { color: cfg.captionActiveColor || bg, background: accent }
      : { color: accent },
    font: {
      family: font,
      size: Number(cfg.captionSize == null ? 64 : cfg.captionSize),
      color: '#ffffff',
      bold: true,
      transform: 'uppercase',
    },
    stroke: { color: '#000000', width: usesBox ? Math.min(strokeWidth, 2) : strokeWidth },
    ...(usesBox ? { background: { padding: 14 } } : {}),
    position: 'center',
    margin: { x: 90, y: 0 },
    maxWordsPerLine: perCue,
  };

  // ---- audio --------------------------------------------------------------
  const upload = data.upload || {};
  if (!upload.url) throw new Error('The voiceover upload returned no URL.');
  // NOTE: no `track` field on audios — the render API rejects audios[].track.
  const audios = [{ src: upload.url, volume: 1, enter: 0 }];
  const music = data.music || null;
  if (music && music.src) {
    audios.push({ src: music.src, volume: Number(cfg.musicVolume == null ? 0.11 : cfg.musicVolume), enter: 0, exit: totalDuration });
  }

  // The render API only allows letters, digits, spaces, _ and - in `name`.
  // Trim the long-niche case on a word boundary: the slug is metadata and is
  // never drawn on screen, but half a word reads like a bug in the editor.
  const rawName = ('weekly-roundup-' + niche + '-' + fmtDay(now)).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  let safeName = rawName;
  if (safeName.length > 60) {
    const cut = safeName.slice(0, 60);
    const brk = cut.lastIndexOf('-');
    safeName = (brk >= 20 ? cut.slice(0, brk) : cut).replace(/-+$/g, '');
  }

  const payload = {
    name: safeName || 'weekly-roundup',
    resolution: cfg.resolution || 'instagram-reel',
    frameRate: Number(cfg.frameRate == null ? 30 : cfg.frameRate),
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes,
    audios,
    subtitle,
  };

  return {
    payload,
    meta: {
      niche,
      dateline,
      storyCount,
      countdown: stories.slice(0, storyCount).map((s, i) => ({ rank: storyCount - i, headline: clean(s.headline), source: clean(s.source) })),
      narrationSeconds: round(audioDuration),
      totalDuration,
      sceneCount: scenes.length,
      captionCount: captions.length,
      captionWordsPerCue: perCue,
      cutsAlignedToSpeech: useWordMap,
      musicTrack: music ? music.description || music.src : null,
      missingClips,
      pooledHeadlines: Number(rundown.pooledCount) || null,
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const built = buildRoundup(config, {
  rundown: $('Parse rundown').first().json,
  sceneMedia: $('Pick story clips').first().json.sceneMedia,
  music: $('Pick music').first().json.music || null,
  upload: $('Upload voiceover').first().json.upload,
  timings: $('Voice + timings').first().json,
});
return [{ json: built }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug - surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// exact video, then set dryRun to false in Config to go live.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    niche: d.meta.niche,
    dateline: d.meta.dateline,
    storyCount: d.meta.storyCount,
    countdown: d.meta.countdown,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalDuration,
    narrationSeconds: d.meta.narrationSeconds,
    captions: d.meta.captionCount,
    cutsAlignedToSpeech: d.meta.cutsAlignedToSpeech,
    musicTrack: d.meta.musicTrack,
    missingClips: d.meta.missingClips,
    warnings: d.warnings,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render for real.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for a live run.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
    brand: cfg.brandName,
    niche: build.meta.niche,
    dateline: build.meta.dateline,
    storyCount: build.meta.storyCount,
    countdown: build.meta.countdown,
    videoSeconds: build.meta.totalDuration,
    captions: build.meta.captionCount,
    cutsAlignedToSpeech: build.meta.cutsAlignedToSpeech,
    musicTrack: build.meta.musicTrack,
    missingClips: build.meta.missingClips,
    creditsCharged: build.creditsRequired,
  },
}];
